const factory = { make<T>(): T { return undefined as T; } };
function consume(value: number): number { return value; }
export const result = consume(factory.make());

const factory = { make<T>(): T { return undefined as T; } };
const key: "make" = "make";
export const result: number = factory[key]();

class Factory { make<T>(): T { return undefined as T; } }
const factory = new Factory();
export const result: number = factory.make();

function make<T>(): T { return undefined as T; }
const factory = { make };
export const result: number = factory.make();

interface Factory { make<T>(): T; make<T>(value: T): T; }
declare const factory: Factory;
export const result: number = factory.make();

const factory = { make<T>(): T { return undefined as T; } };
declare function consume(value: number): "number";
declare function consume(value: string): "string";
export const result = consume(factory.make());
